body.script:
(function () {
    var fil = document.getElementById("chat-fil");
    var entree = document.getElementById("chat-entree");
    var envoi = document.getElementById("chat-envoi");
    var etat = document.getElementById("chat-etat");
    var historique = [];
    var cleChamp = document.getElementById("chat-cle");
    var cleBtn = document.getElementById("chat-cle-enregistrer");
    if (cleBtn) {
        cleBtn.addEventListener("click", function () {
            var cle = cleChamp.value.trim();
            if (!cle) return;
            cleBtn.disabled = true;
            fetch("/community/chat/cle", {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    params: {cle: cle}
                })
            }).then(function (r) { return r.json(); }).then(function (d) {
                var resultat = d && d.result;
                if (resultat && resultat.ok) {
                    var b = document.getElementById("chat-bandeau");
                    if (b) b.remove();
                    cleChamp.value = "";
                    ajouter("ia", "Clé enregistrée. Chloé peut répondre.");
                } else {
                    etat.textContent = (resultat && resultat.erreur) || "Échec.";
                }
            }).catch(function () {
                etat.textContent = "Impossible de joindre le serveur.";
            }).finally(function () {
                cleBtn.disabled = false;
            });
        });
    }
    function ajouter(role, texte) {
        var d = document.createElement("div");
        d.className = "chat-bulle " + (role === "user" ? "chat-moi" : "chat-ia");
        d.textContent = texte;
        fil.appendChild(d);
        fil.scrollTop = fil.scrollHeight;
    }
    function parler() {
        var t = entree.value.trim();
        if (!t) return;
        ajouter("user", t);
        historique.push({role: "user", content: t});
        entree.value = "";
        entree.disabled = true; envoi.disabled = true;
        etat.textContent = "Chloé réfléchit…";
        fetch("/community/chat/message", {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify({
                jsonrpc: "2.0",
                params: {texte: t, historique: historique}
            })
        }).then(function (r) { return r.json(); }).then(function (d) {
            etat.textContent = "";
            var resultat = d && d.result;
            if (!resultat) { ajouter("ia", "Réponse vide du serveur."); return; }
            if (resultat.erreur) { ajouter("ia", resultat.erreur); }
            else {
                ajouter("ia", resultat.reponse);
                historique.push({role: "assistant", content: resultat.reponse});
            }
        }).catch(function () {
            etat.textContent = "";
            ajouter("ia", "Impossible de joindre le serveur.");
        }).finally(function () {
            entree.disabled = false; envoi.disabled = false;
            entree.focus();
        });
    }
    envoi.addEventListener("click", parler);
    entree.addEventListener("keydown", function (e) {
        if (e.key === "Enter") parler();
    });
    entree.focus();
})();
